// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Argument;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Compare;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Constant;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.DecodeInline;
import org.junit.jupiter.api.Test;

/** Slice-form tests (fragment-fusion M2): escape partitions, exact resolution, encounter-order restoration. */
class FragmentSliceTest {

	private static long orderedInt(long value) {
		return ValueIds.createId(ValueIds.T_ORD_INTEGER, value + ValueIds.ORDERED_BIAS);
	}

	private static FragmentIR geConstant() {
		return FragmentIR.predicate(new Compare(FragmentCompareOp.GE,
				new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
				new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER)));
	}

	@Test
	void slicePartitionsMatchScalarEvaluation() {
		LongPredicateFragment fragment = FragmentCompiler.compilePredicate(geConstant());
		FragmentBinding binding = FragmentBinding.of(orderedInt(50));
		Random random = new Random(42);
		long[] column = new long[512];
		for (int i = 0; i < column.length; i++) {
			int kind = random.nextInt(4);
			if (kind == 0) {
				column[i] = -1L;
			} else if (kind == 1) {
				column[i] = ValueIds.createId(ValueIds.T_LITERAL, i);
			} else {
				column[i] = orderedInt(random.nextInt(100));
			}
		}
		int[] inputSel = new int[column.length];
		for (int i = 0; i < inputSel.length; i++) {
			inputSel[i] = i;
		}
		int[] outputSel = new int[column.length];
		int[] escapeSel = new int[column.length];
		long result = FragmentSlices.unary(fragment)
				.select1(column, 0, inputSel, inputSel.length, outputSel, escapeSel, binding);
		List<Integer> expectedAccepted = new ArrayList<>();
		List<Integer> expectedEscaped = new ArrayList<>();
		for (int i = 0; i < column.length; i++) {
			PredicateStatus status = fragment.test(column[i], -1L, -1L, binding);
			if (status == PredicateStatus.TRUE) {
				expectedAccepted.add(i);
			} else if (status == PredicateStatus.ESCAPE) {
				expectedEscaped.add(i);
			}
		}
		assertThat(FragmentSlices.acceptedCount(result)).isEqualTo(expectedAccepted.size());
		assertThat(FragmentSlices.escapedCount(result)).isEqualTo(expectedEscaped.size());
		for (int i = 0; i < expectedAccepted.size(); i++) {
			assertThat(outputSel[i]).isEqualTo(expectedAccepted.get(i));
		}
		for (int i = 0; i < expectedEscaped.size(); i++) {
			assertThat(escapeSel[i]).isEqualTo(expectedEscaped.get(i));
		}
	}

	@Test
	void escapesResolveThroughExactTierAndMergeInEncounterOrder() {
		LongPredicateFragment fragment = FragmentCompiler.compilePredicate(geConstant());
		// exact tier accepts literals with even payloads
		FragmentBinding binding = FragmentBinding.of(orderedInt(10))
				.withFallback((a0, a1, a2) -> ValueIds.getValue(a0) % 2 == 0);
		long[] column = { orderedInt(20), ValueIds.createId(ValueIds.T_LITERAL, 4),
				ValueIds.createId(ValueIds.T_LITERAL, 5), orderedInt(3), orderedInt(11),
				ValueIds.createId(ValueIds.T_LITERAL, 6) };
		int[] inputSel = { 0, 1, 2, 3, 4, 5 };
		int[] outputSel = new int[column.length];
		int[] escapeSel = new int[column.length];
		long result = FragmentSlices.unary(fragment)
				.select1(column, 0, inputSel, inputSel.length, outputSel, escapeSel, binding);
		int[] merged = new int[column.length];
		int survivors = FragmentSlices.resolveEscapes(column, 0, outputSel,
				FragmentSlices.acceptedCount(result), escapeSel, FragmentSlices.escapedCount(result), binding, merged);
		// fast path accepts 0 and 4; escapes 1, 2, 5; exact tier accepts 1 and 5 (even payloads)
		assertThat(survivors).isEqualTo(4);
		assertThat(merged[0]).isEqualTo(0);
		assertThat(merged[1]).isEqualTo(1);
		assertThat(merged[2]).isEqualTo(4);
		assertThat(merged[3]).isEqualTo(5);
	}

	@Test
	void binarySliceMatchesScalarEvaluation() {
		FragmentIR ir = FragmentIR.predicate(new Compare(FragmentCompareOp.LT,
				new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
				new DecodeInline(new Argument(1), DecodeInline.InlineKind.ORDERED_INTEGER)));
		LongPredicateFragment fragment = FragmentCompiler.compilePredicate(ir);
		long[] columnA = { orderedInt(1), orderedInt(9), ValueIds.createId(ValueIds.T_LITERAL, 1), orderedInt(4) };
		long[] columnB = { orderedInt(2), orderedInt(3), orderedInt(5), orderedInt(4) };
		int[] inputSel = { 0, 1, 2, 3 };
		int[] outputSel = new int[4];
		int[] escapeSel = new int[4];
		long result = FragmentSlices.binary(fragment)
				.select2(columnA, columnB, 0, inputSel, 4, outputSel, escapeSel, FragmentBinding.EMPTY);
		assertThat(FragmentSlices.acceptedCount(result)).isEqualTo(1);
		assertThat(outputSel[0]).isEqualTo(0);
		assertThat(FragmentSlices.escapedCount(result)).isEqualTo(1);
		assertThat(escapeSel[0]).isEqualTo(2);
	}

	@Test
	void sliceHonoursBaseOffsetAndSparseSelection() {
		LongPredicateFragment fragment = FragmentCompiler.compilePredicate(geConstant());
		FragmentBinding binding = FragmentBinding.of(orderedInt(0));
		long[] column = new long[16];
		column[8 + 1] = orderedInt(5);
		column[8 + 3] = orderedInt(-5);
		column[8 + 6] = orderedInt(7);
		int[] inputSel = { 1, 3, 6 };
		int[] outputSel = new int[3];
		int[] escapeSel = new int[3];
		long result = FragmentSlices.unary(fragment).select1(column, 8, inputSel, 3, outputSel, escapeSel, binding);
		assertThat(FragmentSlices.acceptedCount(result)).isEqualTo(2);
		assertThat(outputSel[0]).isEqualTo(1);
		assertThat(outputSel[1]).isEqualTo(6);
	}

	@Test
	void mergePreservesAscendingOrderForArbitraryPartitions() {
		int[] left = { 0, 4, 9 };
		int[] right = { 1, 5, 6, 12 };
		int[] merged = new int[7];
		int count = FragmentSlices.mergeAscending(left, 3, right, 4, merged);
		assertThat(count).isEqualTo(7);
		assertThat(merged).containsExactly(0, 1, 4, 5, 6, 9, 12);
	}
}
